<script lang="ts">
 import {enhance} from '$app/forms';import Aviso from '#lib/componentes/Aviso.svelte';import {nomeNaEscala,formatarData} from '#lib/util';let {data,form}=$props();let enviando=$state<number|null>(null);
</script>
