<form class="cartao mt-4 grid gap-3 sm:grid-cols-3" method="POST" action="?/previa" use:enhance><label class="rotulo">De<input class="campo" name="inicio" type="date" required value={data.inicio}/></label><label class="rotulo">Até<input class="campo" name="fim" type="date" required value={data.fim}/></label><button class="btn btn-primario">Calcular prévia</button></form>
{#if data.publicacoes.length}
<section class="cartao mt-4" aria-labelledby="publicacoes-titulo"><h2 id="publicacoes-titulo" class="font-semibold">Escalas publicadas</h2><p class="mt-2 text-sm text-gray-600">Envie um aviso dentro da plataforma a todos os obreiros ativos da área, mesmo aos que não foram escalados.</p>
