{/if}
{#if form&&'previa' in form&&form.previa}
<section class="cartao mt-4"><h2 class="titulo">Prévia · {form.previa.propostas.length} escala(s)</h2><p class="text-sm mt-2">Ainda não foi salvo nenhum escalado desta prévia.</p>{#each form.previa.propostas as p (p.culto_id)}<article class="border-b py-3 text-sm"><strong>{nomeNaEscala(p)}</strong><p>{formatarData(p.data)} · {p.hora_inicio} · {p.nome_evento||p.tipo} · {p.congregacao}</p><p>{p.anteriores} escala(s) antes desta escolha</p></article>{/each}
